function ClientVersusRespawn(optional bool bPreserveLiveCamera)
{
    bVersusDead = False;
    bPreserveVersusCameraOnSetup = bPreserveLiveCamera
        && IsLocalViewportPlayer() && Cam != None;
    SetupVersusPlayer();
    bPreserveVersusCameraOnSetup = False;
}

// Harry's idle_1/fidget variants contain bones that are not safe on every
// linked cosmetic skeleton. The common Idle sequence is present in the
// accepted player set and keeps new roster characters out of reference pose.
function bool UsesStableVersusIdle()
{
    return class'HPVersusCharacterProfiles'.static.ShouldLinkHarryAnimations(Mesh);
}

function name GetCurrIdleAnimName()
{
    if (UsesStableVersusIdle())
        return HarryAnims[HarryAnimSet].Idle;

    return Super.GetCurrIdleAnimName();
}

function name GetCurrFidgetAnimName()
{
    if (UsesStableVersusIdle())
        return HarryAnims[HarryAnimSet].Idle;

    return Super.GetCurrFidgetAnimName();
}

